import fs from 'fs';
import path from 'path';
import { eq } from 'drizzle-orm';
import { drizzle } from 'drizzle-orm/node-sqlite';
import { metadataState } from '../project-metadata/schema';

const SOURCE_SCHEMA_VERSION = 1;
const PRESENTATION_KEY = 'variants_ui_state';

export const readSourcePresentation = async (
  dataDirectory: string,
): Promise<string | null> => {
  const filename = path.join(dataDirectory, 'rivet.db');
  if (!fs.existsSync(filename)) return null;
  const { DatabaseSync } = await import('node:sqlite');
  const client = new DatabaseSync(filename, { readOnly: true });
  try {
    const version = Number(
      client.prepare('PRAGMA user_version').get()?.user_version,
    );
    if (version !== SOURCE_SCHEMA_VERSION)
      throw new Error(`Unsupported source metadata schema: ${version}`);
    const db = drizzle({ client });
    return (
      db
        .select({ value: metadataState.value })
        .from(metadataState)
        .where(eq(metadataState.key, PRESENTATION_KEY))
        .get()?.value ?? null
    );
  } finally {
    client.close();
  }
};
